actions.script:
if (testPassed !== 'Y' && continueAnyway !== 'Y') ec.message.addValidationError(null, 'continueAnyway', null,
    ec.l10n.localize('The test did not pass: go back to fix the setup, or choose Continue anyway'), null)
if (!ec.message.hasError()) {
    ec.web.sessionAttributes.remove('edgeSetup')
    ec.web.sessionAttributes.remove('edgeApplied')
    ec.web.sessionAttributes.remove('edgeTested')
}

const L = (text) => ec.l10n.localize(text)
const link = ec.service.sync().name('org.moqui.impl.EdgeServices.get#LinkStatus').call() || {}
notBuilt = link.state === 'notBuilt'
notStarted = link.state === 'notStarted'
const running = !notBuilt && !notStarted
// an edge or all-in-one node takes links; the wizard is a local node's (plans/Edge-Node.md §10)
isEdge = running && ['edge', 'all-in-one'].includes(link.nodeRole)
notPaired = running && !isEdge && (!link.state || link.state === 'unpaired')
let choices = null
try { choices = JSON.parse(ec.web.sessionAttributes.edgeSetup || 'null') } catch (e) { choices = null }
noChoices = running && !isEdge && !notPaired && !choices
ready = running && !isEdge && !notPaired && !!choices
testRows = []
testError = ''
passed = false
if (!ready) return
// the address mail in is checked for: the first chosen account's
const firstAccount = (choices.emailAccountIds || [])[0]
const account = firstAccount ? ec.entity.find('moqui.basic.email.EmailAccount').condition('emailAccountId', firstAccount)
    .disableAuthz().one() : null
// the result of this visit's test, else a new one; a probe (Practices-App-Dev §4): a failure is shown, not raised
let out = null
try { out = JSON.parse(ec.web.sessionAttributes.edgeTested || 'null') } catch (e) { out = null }
if (!out) {
    ec.message.pushErrors()
    try {
        const tested = ec.service.sync().name('org.moqui.impl.EdgeServices.test#EdgeSetup').parameters({
            mailOn: !!choices.mailOn, mailAddress: account?.emailAddress || '',
            systemMail: !!choices.systemMail, emailAccountIds: choices.emailAccountIds || [],
            chatOn: !!choices.chatOn, chatBridgeIds: choices.chatBridgeIds || [],
            passOn: !!choices.passOn, passSites: choices.passSites || [], xmppOn: !!choices.xmppOn,
            callsOn: !!choices.callsOn, sipOn: !!choices.sipOn}).call() || {}
        if (ec.message.hasError()) testError = ec.message.getErrorsString()
        out = {passed: tested.passed === true, testList: Array.from(tested.testList || []).map((test) =>
            ({label: test.label, message: test.message, ok: test.ok === true, checked: test.checked !== false}))}
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
    }
    if (!testError) ec.web.sessionAttributes.edgeTested = JSON.stringify(out)
}
passed = !testError && out.passed === true
testRows = Array.from(out.testList || []).map((test) => ({label: test.label, message: test.message,
    stateLabel: !test.checked ? L('Not checked') : test.ok ? L('Passed') : L('Failed'),
    stateColor: !test.checked ? 'grey' : test.ok ? 'positive' : 'negative'}))
confirm = {testPassed: passed ? 'Y' : 'N', continueAnyway: ''}
